function jsonPath(string $name): string { global $root; return $root.'/data/'.$name.'.json'; }
function readJson(string $name, $fallback = []) { $p=jsonPath($name); if(!is_file($p)) return $fallback; $v=json_decode((string)file_get_contents($p),true); return is_array($v)?$v:$fallback; }
function writeJson(string $name, $data): bool { $json=json_encode($data,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); return $json!==false && file_put_contents(jsonPath($name),$json.PHP_EOL,LOCK_EX)!==false; }
function h($v): string { return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8'); }
$tab=$_GET['tab']??'dashboard';
