  } elseif($action==='delete_request'){
    $items=array_values(array_filter(readJson('requests',[]),fn($r)=>($r['id']??'')!==$_POST['id'])); writeJson('requests',$items); $message='So‘rov o‘chirildi.'; $tab='requests';
  } elseif($action==='save_site'){
