  } elseif($action==='save_services'){
    $data=readJson('services',[]); $data['intro']=trim((string)($_POST['intro']??'')); writeJson('services',$data); $tab='services'; $message='Services ma’lumotlari saqlandi.';
  } elseif($action==='save_portfolio'){
    $data=readJson('portfolio',[]); $data['intro']=trim((string)($_POST['intro']??'')); writeJson('portfolio',$data); $tab='portfolio'; $message='Portfolio ma’lumotlari saqlandi.';
  } elseif($action==='upload'){
    $type=$_POST['type']??'image'; $dir=$type==='video'?$root.'/media/videos/':$root.'/media/images/'; $allowedMime=$type==='video'?['video/mp4','video/webm','video/quicktime']:['image/jpeg','image/png','image/webp','image/gif']; $max=$type==='video'?50*1024*1024:10*1024*1024;
    if(isset($_FILES['media']) && $_FILES['media']['error']===UPLOAD_ERR_OK && $_FILES['media']['size']<=$max){$f=$_FILES['media'];$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ext=strtolower(pathinfo($f['name'],PATHINFO_EXTENSION));$safeExt=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif','video/mp4'=>'mp4','video/webm'=>'webm','video/quicktime'=>'mov'][$mime]??'';if(in_array($mime,$allowedMime,true)&&$safeExt){if(!is_dir($dir))mkdir($dir,0755,true);$name=bin2hex(random_bytes(12)).'.'.$safeExt;if(move_uploaded_file($f['tmp_name'],$dir.$name))$message='Media yuklandi: '.$name;else $message='Media saqlanmadi.';}else $message='Fayl turi ruxsat etilmagan.';}else $message='Fayl xatosi yoki hajmi limitdan oshgan.'; $tab='media';
  }
}
